proguardAdditions.insert:
-keepattributes Signature
-keep class com.epicgames.unreal.GameActivity { public native <methods>; }
-keep class com.epicgames.ue4.GameActivity { public native <methods>; }

gameActivityImportAdditions.insert:
import android.os.Build;
import android.util.DisplayMetrics;
import android.view.Gravity;
import android.view.View;
import android.view.WindowMetrics;
import android.widget.FrameLayout;
import androidx.annotation.NonNull;
import com.google.android.gms.ads.AdError;
import com.google.android.gms.ads.AdListener;
import com.google.android.gms.ads.AdRequest;
import com.google.android.gms.ads.AdSize;
import com.google.android.gms.ads.AdView;
import com.google.android.gms.ads.FullScreenContentCallback;
import com.google.android.gms.ads.LoadAdError;
import com.google.android.gms.ads.MobileAds;
import com.google.android.gms.ads.OnUserEarnedRewardListener;
import com.google.android.gms.ads.RequestConfiguration;
import com.google.android.gms.ads.initialization.InitializationStatus;
import com.google.android.gms.ads.initialization.OnInitializationCompleteListener;
import com.google.android.gms.ads.interstitial.InterstitialAd;
import com.google.android.gms.ads.interstitial.InterstitialAdLoadCallback;
import com.google.android.gms.ads.rewarded.RewardItem;
import com.google.android.gms.ads.rewarded.RewardedAd;
import com.google.android.gms.ads.rewarded.RewardedAdLoadCallback;
import com.google.android.ump.ConsentDebugSettings;
import com.google.android.ump.ConsentForm;
import com.google.android.ump.ConsentInformation;
import com.google.android.ump.ConsentRequestParameters;
import com.google.android.ump.FormError;
import com.google.android.ump.UserMessagingPlatform;
import java.util.Arrays;

gameActivityClassAdditions.insert:
// --------------- AdBox (AdMob) Begin ---------------
private ConsentInformation adBoxConsentInfo = null;
private boolean adBoxAdsInitialized = false;

private InterstitialAd adBoxInterstitial = null;

private AdView adBoxBannerView = null;
private boolean adBoxBannerLoaded = false;
private boolean adBoxBannerWantsShown = false;

private RewardedAd adBoxRewardedAd = null;
private boolean isRewardedAdLoaded = false;
private boolean isRewardedAdRequested = false;

// Callback ke C++ (diimplement di AdMobFunctionLibrary.cpp)
public static native void CPPRewardAd(int index);
public static native void CPPUserEarnRewardAd(String rewardType, int amount);

private boolean adBoxCanRequestAds()
{
  return adBoxConsentInfo != null && adBoxConsentInfo.canRequestAds();
}

private void adBoxStartMobileAds()
{
  if (adBoxAdsInitialized || !adBoxCanRequestAds())
  {
    return;
  }
  adBoxAdsInitialized = true;
  final GameActivity activity = this;
  // Rekomendasi Google: initialize di background thread biar gak ANR
  new Thread(new Runnable()
  {
    @Override public void run()
    {
      MobileAds.initialize(activity, new OnInitializationCompleteListener()
      {
        @Override public void onInitializationComplete(@NonNull InitializationStatus status)
        {
          Log.debug("AdBox: MobileAds initialized");
        }
      });
    }
  }).start();
}

// Dipanggil dari onCreate: UMP consent flow (wajib sejak SDK 22+)
private void AdBoxInitAdMob()
{
  RequestConfiguration.Builder configBuilder = new RequestConfiguration.Builder();
  // Buat testing, uncomment + isi hashed device ID dari logcat:
  // configBuilder.setTestDeviceIds(Arrays.asList("HASHED_TEST_DEVICE_ID"));
  MobileAds.setRequestConfiguration(configBuilder.build());

  ConsentRequestParameters.Builder paramsBuilder = new ConsentRequestParameters.Builder();
  // Debug consent (simulasi region EEA), cuma jalan di test device:
  // ConsentDebugSettings debugSettings = new ConsentDebugSettings.Builder(this)
  //     .setDebugGeography(ConsentDebugSettings.DebugGeography.DEBUG_GEOGRAPHY_EEA)
  //     .addTestDeviceHashedId("HASHED_TEST_DEVICE_ID")
  //     .build();
  // paramsBuilder.setConsentDebugSettings(debugSettings);

  final GameActivity activity = this;
  adBoxConsentInfo = UserMessagingPlatform.getConsentInformation(this);
  adBoxConsentInfo.requestConsentInfoUpdate(this, paramsBuilder.build(),
    new ConsentInformation.OnConsentInfoUpdateSuccessListener()
    {
      @Override public void onConsentInfoUpdateSuccess()
      {
        // Consent mungkin udah ada dari sesi sebelumnya
        adBoxStartMobileAds();
        UserMessagingPlatform.loadAndShowConsentFormIfRequired(activity,
          new ConsentForm.OnConsentFormDismissedListener()
          {
            @Override public void onConsentFormDismissed(FormError formError)
            {
              if (formError != null)
              {
                Log.debug("AdBox: consent form error: " + formError.getMessage());
              }
              adBoxStartMobileAds();
            }
          });
      }
    },
    new ConsentInformation.OnConsentInfoUpdateFailureListener()
    {
      @Override public void onConsentInfoUpdateFailure(@NonNull FormError formError)
      {
        Log.debug("AdBox: consent update failed: " + formError.getMessage());
        adBoxStartMobileAds();
      }
    });
}

// --------------- Interstitial ---------------
public void AndroidThunkJava_ShowAdBoxInterstitial(String adUnitId)
{
  Log.debug("AdBox: ShowInterstitial " + adUnitId);
  if (!adBoxCanRequestAds())
  {
    Log.debug("AdBox: consent belum siap, interstitial dibatalkan");
    return;
  }
  final GameActivity activity = this;
  final String unitId = adUnitId;
  runOnUiThread(new Runnable()
  {
    @Override public void run()
    {
      InterstitialAd.load(activity, unitId, new AdRequest.Builder().build(),
        new InterstitialAdLoadCallback()
        {
          @Override public void onAdLoaded(@NonNull InterstitialAd interstitialAd)
          {
            adBoxInterstitial = interstitialAd;
            adBoxInterstitial.setFullScreenContentCallback(new FullScreenContentCallback()
            {
              @Override public void onAdDismissedFullScreenContent()
              {
                adBoxInterstitial = null;
              }
              @Override public void onAdFailedToShowFullScreenContent(@NonNull AdError adError)
              {
                Log.debug("AdBox: interstitial gagal tampil: " + adError.getMessage());
                adBoxInterstitial = null;
              }
            });
            adBoxInterstitial.show(activity);
          }
          @Override public void onAdFailedToLoad(@NonNull LoadAdError loadAdError)
          {
            Log.debug("AdBox: interstitial gagal load: " + loadAdError.getMessage());
            adBoxInterstitial = null;
          }
        });
    }
  });
}

// --------------- Banner (large anchored adaptive, API v25) ---------------
private int adBoxBannerWidthDp()
{
  float density = getResources().getDisplayMetrics().density;
  int widthPx;
  if (Build.VERSION.SDK_INT >= 30)
  {
    WindowMetrics metrics = getWindowManager().getCurrentWindowMetrics();
    widthPx = metrics.getBounds().width();
  }
  else
  {
    DisplayMetrics dm = getResources().getDisplayMetrics();
    widthPx = dm.widthPixels;
  }
  return (int)(widthPx / density);
}

public void AndroidThunkJava_ShowAdBoxBanner(String adUnitId)
{
  Log.debug("AdBox: ShowBanner " + adUnitId);
  if (!adBoxCanRequestAds())
  {
    Log.debug("AdBox: consent belum siap, banner dibatalkan");
    return;
  }
  final GameActivity activity = this;
  final String unitId = adUnitId;
  runOnUiThread(new Runnable()
  {
    @Override public void run()
    {
      adBoxBannerWantsShown = true;
      if (adBoxBannerView == null)
      {
        adBoxBannerView = new AdView(activity);
        adBoxBannerView.setAdUnitId(unitId);
        // Pengganti AdSize.BANNER + getCurrentOrientation... yang deprecated di v25
        adBoxBannerView.setAdSize(AdSize.getLargeAnchoredAdaptiveBannerAdSize(activity, adBoxBannerWidthDp()));
        adBoxBannerView.setVisibility(View.GONE);
        adBoxBannerView.setAdListener(new AdListener()
        {
          @Override public void onAdLoaded()
          {
            adBoxBannerLoaded = true;
            if (adBoxBannerWantsShown && adBoxBannerView != null)
            {
              adBoxBannerView.setVisibility(View.VISIBLE);
              adBoxBannerView.resume();
            }
          }
          @Override public void onAdFailedToLoad(@NonNull LoadAdError loadAdError)
          {
            adBoxBannerLoaded = false;
            Log.debug("AdBox: banner gagal load: " + loadAdError.getMessage());
          }
        });
        // Langsung ke content view, gak pakai PopupWindow hack lama
        FrameLayout content = (FrameLayout)activity.findViewById(android.R.id.content);
        FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(
          FrameLayout.LayoutParams.MATCH_PARENT,
          FrameLayout.LayoutParams.WRAP_CONTENT,
          Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL);
        content.addView(adBoxBannerView, lp);
      }
      else
      {
        adBoxBannerView.setVisibility(View.VISIBLE);
        adBoxBannerView.resume();
      }
      if (!adBoxBannerLoaded)
      {
        adBoxBannerView.loadAd(new AdRequest.Builder().build());
      }
    }
  });
}

public void AndroidThunkJava_CloseAdBoxBanner()
{
  Log.debug("AdBox: CloseBanner");
  runOnUiThread(new Runnable()
  {
    @Override public void run()
    {
      adBoxBannerWantsShown = false;
      if (adBoxBannerView != null)
      {
        adBoxBannerView.pause();
        adBoxBannerView.setVisibility(View.GONE);
      }
    }
  });
}

// --------------- Rewarded ---------------
public boolean AndroidThunkJava_IsRewardedVideoAvailable_AdMob()
{
  return isRewardedAdLoaded;
}

public void AndroidThunkJava_LoadRewardedVideo_AdMob(String adUnitId)
{
  if (isRewardedAdRequested)
  {
    return;
  }
  if (!adBoxCanRequestAds())
  {
    Log.debug("AdBox: consent belum siap, rewarded dibatalkan");
    CPPRewardAd(2);
    return;
  }
  isRewardedAdRequested = true;
  isRewardedAdLoaded = false;
  final GameActivity activity = this;
  final String unitId = adUnitId;
  runOnUiThread(new Runnable()
  {
    @Override public void run()
    {
      RewardedAd.load(activity, unitId, new AdRequest.Builder().build(),
        new RewardedAdLoadCallback()
        {
          @Override public void onAdLoaded(@NonNull RewardedAd rewardedAd)
          {
            adBoxRewardedAd = rewardedAd;
            isRewardedAdLoaded = true;
            isRewardedAdRequested = false;
            CPPRewardAd(1);
          }
          @Override public void onAdFailedToLoad(@NonNull LoadAdError loadAdError)
          {
            Log.debug("AdBox: rewarded gagal load: " + loadAdError.getMessage());
            adBoxRewardedAd = null;
            isRewardedAdLoaded = false;
            isRewardedAdRequested = false;
            CPPRewardAd(2);
          }
        });
    }
  });
}

public void AndroidThunkJava_PlayRewardedVideo_AdMob()
{
  if (!isRewardedAdLoaded || adBoxRewardedAd == null)
  {
    Log.debug("AdBox: rewarded belum siap");
    return;
  }
  isRewardedAdLoaded = false;
  final GameActivity activity = this;
  runOnUiThread(new Runnable()
  {
    @Override public void run()
    {
      adBoxRewardedAd.setFullScreenContentCallback(new FullScreenContentCallback()
      {
        @Override public void onAdShowedFullScreenContent()
        {
          CPPRewardAd(3);
        }
        @Override public void onAdFailedToShowFullScreenContent(@NonNull AdError adError)
        {
          Log.debug("AdBox: rewarded gagal tampil: " + adError.getMessage());
          adBoxRewardedAd = null;
          CPPRewardAd(4);
        }
        @Override public void onAdDismissedFullScreenContent()
        {
          adBoxRewardedAd = null;
          CPPRewardAd(5);
        }
      });
      adBoxRewardedAd.show(activity, new OnUserEarnedRewardListener()
      {
        @Override public void onUserEarnedReward(@NonNull RewardItem rewardItem)
        {
          CPPUserEarnRewardAd(rewardItem.getType(), rewardItem.getAmount());
        }
      });
    }
  });
}

// --------------- Privacy options (UMP, wajib ada entry point-nya) ---------------
public boolean AndroidThunkJava_IsAdBoxPrivacyOptionsRequired()
{
  return adBoxConsentInfo != null
    && adBoxConsentInfo.getPrivacyOptionsRequirementStatus() == ConsentInformation.PrivacyOptionsRequirementStatus.REQUIRED;
}

public void AndroidThunkJava_ShowAdBoxPrivacyOptions()
{
  final GameActivity activity = this;
  runOnUiThread(new Runnable()
  {
    @Override public void run()
    {
      UserMessagingPlatform.showPrivacyOptionsForm(activity,
        new ConsentForm.OnConsentFormDismissedListener()
        {
          @Override public void onConsentFormDismissed(FormError formError)
          {
            if (formError != null)
            {
              Log.debug("AdBox: privacy options error: " + formError.getMessage());
            }
          }
        });
    }
  });
}
// --------------- AdBox End ---------------
